<script setup>
import {ref,onMounted} from 'vue'
const base=import.meta.env.VITE_QUANT_API_URL||'http://127.0.0.1:8000',loading=ref(true),error=ref(''),health=ref(null),status=ref(null),history=ref([])
async function load(){loading.value=true;error.value='';try{const responses=await Promise.all([fetch(`${base}/health`),fetch(`${base}/api/quant/pipeline/status`),fetch(`${base}/api/quant/backtest/history?limit=10`)]);if(responses.some(r=>!r.ok))throw new Error('量化服务返回异常');[health.value,status.value]=await Promise.all([responses[0].json(),responses[1].json()]);history.value=(await responses[2].json()).items||[]}catch(e){error.value=`无法连接量化服务：${e.message}`}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h2>量化运维</h2><p>只读检查流水线、快照、数据覆盖和回测记录。</p></div><button class="btn secondary" @click="load">刷新</button></div><div class="notice" style="background:#edf3ff;color:#355e91">本页面不会触发行情同步、模型运行或交易。</div><div v-if="error" class="notice">{{error}}</div><div v-if="loading" class="loading">正在连接量化服务…</div><template v-else-if="status"><section class="grid metrics"><article class="card metric"><span>服务状态</span><strong>{{health?.status==='ok'?'在线':'异常'}}</strong><small>{{health?.time}}</small></article><article class="card metric"><span>最新快照</span><strong style="font-size:23px">{{status.snapshot?.updatedAt?.slice(0,10)||'暂无'}}</strong><small>{{status.snapshot?.mode||'unknown'}}</small></article><article class="card metric"><span>股票覆盖</span><strong>{{status.snapshot?.stockCount||0}}</strong><small>当前评分记录</small></article><article class="card metric"><span>采集失败</span><strong>{{status.collection?.failedCount||0}}</strong><small>{{status.collection?.spotSource||'暂无来源'}}</small></article></section><section class="grid two-col"><article class="card"><h3>快照与模型</h3><div class="kpi-list"><div><span>模型版本</span><b>{{status.snapshot?.modelVersion||'—'}}</b></div><div><span>参数指纹</span><code>{{status.snapshot?.paramFingerprint||'—'}}</code></div><div><span>采集时间</span><b>{{status.collection?.collectedAt||'—'}}</b></div><div><span>历史来源</span><b>{{status.collection?.historySource||'—'}}</b></div><div><span>财务来源</span><b>{{status.collection?.financialSource||'—'}}</b></div></div></article><article class="card"><h3>数据源状态</h3><div class="kpi-list"><div v-for="s in status.snapshot?.sources||[]" :key="s.name"><span>{{s.name}}</span><b :class="['badge',{warn:s.state!=='online'}]">{{s.state}}</b></div><div v-if="!status.snapshot?.sources?.length" class="empty">暂无来源信息</div></div></article></section><section class="card" style="margin-top:14px"><h3>最近回测</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>运行时间</th><th>样本区间</th><th>收益</th><th>回撤</th><th>状态</th></tr></thead><tbody><tr v-for="(row,i) in history" :key="row.id||i"><td>{{row.createdAt||row.created_at||'—'}}</td><td>{{row.startDate||row.start_date||'—'}} — {{row.endDate||row.end_date||'—'}}</td><td>{{row.totalReturn==null?'—':`${(row.totalReturn*100).toFixed(2)}%`}}</td><td>{{row.maxDrawdown==null?'—':`${(row.maxDrawdown*100).toFixed(2)}%`}}</td><td><span class="badge">{{row.status||'completed'}}</span></td></tr></tbody></table><div v-if="!history.length" class="empty">暂无回测历史</div></div></section></template></div></template>
